create policy "Disable all access"
on "platform"."admins"
as permissive
for all
to public
using (false);


create policy "Admin only"
on "platform"."conversation_tags"
as permissive
for all
to public
using (( SELECT admin_check() AS admin_check))
with check ((admin_id = ( SELECT platform.get_admin_id() AS get_admin_id)));


create policy "Admin access"
on "platform"."tags"
as permissive
for all
to public
using (( SELECT admin_check() AS admin_check))
with check ((admin_id = ( SELECT platform.get_admin_id() AS get_admin_id)));



set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.admin_check()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$declare
  uid uuid;
  is_admin boolean;
begin
  -- Get the current user ID from the JWT using auth.uid()
  select auth.uid() into uid;
  
  if uid is null then
    return false;
  end if;

  select exists(select 1 from platform.admins where auth_id = uid) into is_admin;
  return is_admin;
end;$function$
;


